//! Factory for creating MCP clients from server configuration.//!//! Encapsulates the transport dispatch logic (stdio, Unix socket, HTTP)//! so that callers don't need to match on `EffectiveTransport` themselves.use std::sync::Arc;use crate::secrets::SecretsStore;use crate::tools::mcp::config::{EffectiveTransport, McpServerConfig};use crate::tools::mcp::{McpClient, McpProcessManager, McpSessionManager, McpTransport};/// Error returned when MCP client creation fails.#[derive(Debug, thiserror::Error)]pub enum McpFactoryError {    #[error("Failed to spawn stdio MCP server '{name}': {reason}")]    StdioSpawn { name: String, reason: String },    #[error("Failed to connect to Unix MCP server '{name}': {reason}")]    UnixConnect { name: String, reason: String },    #[error("Unix socket transport is not supported on this platform (server '{name}')")]    UnixNotSupported { name: String },    #[error("Invalid configuration for MCP server '{name}': {reason}")]    InvalidConfig { name: String, reason: String },}/// Create an `McpClient` from a server configuration, dispatching on the/// effective transport type.